def supervise():
    """Keeps Chandra open. On Windows the program runs as a child of this tiny parent; if the child dies the way a crash does
    (an access violation or a fatal error, not a normal close, not End task) it is started again, a few times, and the
    exit code goes in the start log so the cause can be found. A normal close ends both."""
    import subprocess
    env = dict(os.environ, CHANDRA_CHILD="1")
    cmd = [sys.executable, str(Path(__file__).resolve())] + sys.argv[1:]
    try: STORE.mkdir(parents=True, exist_ok=True); err = open(STORE / "chandra-stderr.log", "ab")
    except Exception: err = subprocess.DEVNULL
    crashes = []
    while True:
        t0 = time.time()
        try: code = subprocess.call(cmd, env=env, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=err)
        except Exception as e:
            start_log("supervisor: could not start the program: %r" % (e,)); return 1
        up = int(time.time() - t0)
        crashed = code < 0 or code >= 0xC0000000 or code == 3
        if not crashed: return code
        start_log("supervisor: Chandra stopped with code %s (0x%X) after %d s; starting it again" % (code, code & 0xFFFFFFFF, up))
        now = time.time(); crashes = [t for t in crashes if now - t < 600] + [now]
        if len(crashes) > 4 or (up < 4 and len(crashes) > 2):
            notify("Chandra keeps closing.\n\nDetails are in " + str(START_LOG) + " and " + str(STORE / "chandra-crash.log")); return code
        time.sleep(1.5)


if __name__ == "__main__":
    # pythonw.exe has no console: keep errors in the start log instead of losing them
    if sys.stdout is None: sys.stdout = open(os.devnull, "w", encoding="utf-8")
    if sys.stderr is None:
        try: STORE.mkdir(parents=True, exist_ok=True); sys.stderr = open(STORE / "chandra-stderr.log", "a", encoding="utf-8", buffering=1)
        except Exception: sys.stderr = open(os.devnull, "w", encoding="utf-8")
    if OS == "Windows" and not os.environ.get("CHANDRA_CHILD") and not os.environ.get("CHANDRA_NO_SUPERVISE") \
            and not any(a in sys.argv for a in ("--browser", "--no-window")):
        sys.exit(supervise())
    try:                                      # a native crash leaves its Python stack here (shown in Diagnostics)
        import faulthandler; STORE.mkdir(parents=True, exist_ok=True)
        _crash_fh = open(STORE / "chandra-crash.log", "a", encoding="utf-8", buffering=1); faulthandler.enable(_crash_fh, all_threads=True)
    except Exception: pass
    try:
        main()
    except SystemExit:
        raise
    except BaseException as e:
        import traceback
        start_log("startup failed:\n" + traceback.format_exc())
        notify("Chandra could not start: %s: %s\n\nDetails are in %s" % (type(e).__name__, str(e)[:300], START_LOG))
        time.sleep(15)                        # let the message stay up after the process would have exited
